import openpyxl

wb = openpyxl.load_workbook('/workspace/task/output.xlsx')
ws = wb['Sheet1']

# Build lookup from G:H (rows 5-10)
lookup = {}
for r in range(5, 11):
    code = ws.cell(row=r, column=7).value
    grp = ws.cell(row=r, column=8).value
    if code is not None and grp is not None:
        lookup[str(code).strip()] = str(grp).strip()

def groupnum(g):
    # extract trailing number from "Group 1"
    return int(''.join(ch for ch in g if ch.isdigit()) or 0)

for r in range(5, 11):
    c = ws.cell(row=r, column=3).value
    if c is None:
        continue
    codes = [x.strip() for x in str(c).split(';') if x.strip()]
    groups = []
    for code in codes:
        g = lookup.get(code)
        if g and g not in groups:
            groups.append(g)
    groups.sort(key=groupnum)
    result = ', '.join(groups)
    ws.cell(row=r, column=4).value = result
    print(r, repr(c), '->', repr(result))

wb.save('/workspace/task/output.xlsx')
print('saved')
